"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type PressTapFeedbackPrimitiveProps = ComponentProps<typeof motion.div>;

export function PressTapFeedbackPrimitive({ children, ...props }: PressTapFeedbackPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      whileTap={reduceMotion ? undefined : {scale: 0.96}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.12, ease: [0.16, 1, 0.3, 1] }}
    >
      {children}
    </motion.div>
  );
}
